interface apb_if(input pclk,
                 input presetn);

  logic[31:0] paddr;
  logic[31:0] prdata;
  logic[31:0] pwdata;
  logic[15:0] psel; // only connect the ones that are needed
  logic penable;
  logic pwrite;
  logic pready;
  logic pslverr;

  property psel_valid;
    @(posedge pclk)
    !$isunknown(psel);
  endproperty: psel_valid

  chk_psel: assert property(psel_valid);

  cover_psel: cover property(psel_valid);

endinterface: apb_if

