class uart_driver extends uvm_driver #(uart_seq_item, uart_seq_item);

`uvm_component_utils(uart_driver)

function new(string name = "uart_driver", uvm_component parent = null);
  super.new(name, parent);
endfunction

virtual serial_if sline;

uart_seq_item pkt;

bit clk;
logic[15:0] divisor;

task send_pkts;
// receives a character according to the appropriate word format
  integer bitptr = 0;
  begin
    sline.sdata = 1;
    forever
      begin
        seq_item_port.get_next_item(pkt);
        divisor = pkt.baud_divisor;
        // variable delay
        repeat(pkt.delay)
          @(posedge sline.clk);
        if (pkt.sbe)
          begin
            sline.sdata = 0;
            repeat(pkt.sbe_clks)
              @(posedge sline.clk);
            sline.sdata = 1;
            repeat(pkt.sbe_clks)
              @(posedge sline.clk);
          end
        // start bit
        sline.sdata = 0;
        bitptr = 0;
        bitperiod;
        // data bits 0 to 4
        while(bitptr < 5)
          begin
            sline.sdata = pkt.data[bitptr];
            bitperiod;
            bitptr++;
          end
        // data bits 5 to 7
        if (pkt.lcr[1:0] > 2'b00)
          begin
            sline.sdata = pkt.data[5];
            bitperiod;
          end
        if (pkt.lcr[1:0] > 2'b01)
          begin
            sline.sdata = pkt.data[6];
            bitperiod;
          end
        if (pkt.lcr[1:0] > 2'b10)
          begin
            sline.sdata = pkt.data[7];
            bitperiod;
          end
        // parity
        if (pkt.lcr[3])
          begin
            sline.sdata = logic'(calparity(pkt.lcr, pkt.data));
            if (pkt.pe)
              sline.sdata = ~sline.sdata;
            bitperiod;
          end
        // stop bit
        if (!pkt.fe)
          sline.sdata = 1;
        else
          sline.sdata = 0;
        bitperiod;
        if (!pkt.fe)
          begin
            if (pkt.lcr[2])
              begin
                if (pkt.lcr[1:0] == 2'b00)
                  begin
                    repeat(8)
                      @(posedge sline.clk);
                  end
                else
                  bitperiod;
              end
          end
        else
          begin
            sline.sdata = 1;
            bitperiod;
          end
        seq_item_port.item_done();
      end
  end
endtask: send_pkts

task bitperiod;
  begin
    repeat(16)
      @(posedge sline.clk);
  end
endtask: bitperiod

task run_phase(uvm_phase phase);
    send_pkts;
endtask: run_phase


endclass: uart_driver

