//   the license for the specific language governing
//   permissions and limitations under the license.
//------------------------------------------------------------

class uart_monitor extends uvm_component;

`uvm_component_utils(uart_monitor)

uvm_analysis_port #(uart_seq_item) ap;

virtual serial_if sline;

uart_agent_config cfg;

logic[15:0] divisor;

uart_seq_item s_char;

bit sbe;
bit pe;
bit fe;
logic clk;
logic parity;

logic[7:0] rxdata;

function new(string name = "uart_monitor", uvm_component parent = null);
  super.new(name, parent);
endfunction

function void build_phase(uvm_phase phase);
  ap = new("uart_ap", this);
  if (!uvm_config_db #(uart_agent_config)::get(this, "", "uart_agent_config", cfg) )
     `uvm_fatal("config_load", "cannot get() configuration uart_agent_config from uvm_config_db. have you set() it?")
  divisor = cfg.baud_divisor;
  s_char = new("serial_character");
endfunction: build_phase

task run_phase(uvm_phase phase);
  begin
    repeat(3)
    @(posedge sline.clk);
    forever
      begin
        fork
          rxchar;
          startbiterrordetect;
        join_any
        if (sbe == 1)
            disable fork;
        if (sbe == 0)
          begin
            s_char.data = rxdata;
            s_char.pe = pe;
            s_char.fe = fe;
            ap.write(s_char);
            rxdata = 0;
          end
       end
  end
endtask : run_phase

task startbiterrordetect;
 automatic integer i;
 automatic int startbit = 0;
   begin
     sbe = 0;
     s_char.sbe = 0;
     i = 0;
     while((sline.sdata == 1'b1) || (sline.sdata == 1'bx))
       @(posedge clk);
       startbit = 1;
     begin : startbiterrordetect
       startbit = 99;
       while ((sbe != 1) && i<8)
         begin
           @(posedge sline.clk);
           if(sline.sdata == 1'b1)
             begin
               `uvm_warning("startbiterrordetect", "false start bit detected")
               startbit = 88;
               sbe = 1;
               s_char.sbe = 1;
             end
             i++;
             startbit = i;
         end
       if (!sbe)
         forever
           @(posedge sline.clk);
      end : startbiterrordetect
   end
endtask

task rxchar;
  automatic int startbit= 0;
// receives a character according to the appropriate word format
  begin
    // wait for a falling edge on txd
    fe = 0;
    rxdata = 0;
     while((sline.sdata == 1'b1) || (sline.sdata == 1'bx))
       @(posedge sline.clk);
     startbit = 1;
     begin : rxchardetect
      repeat(23) // sample on mid point of data field
        @(posedge sline.clk);
      startbit = 0;
      rxdata[0] = sline.sdata;
      bitperiod;
      rxdata[1] = sline.sdata;
      bitperiod;
      rxdata[2] = sline.sdata;
      bitperiod;
      rxdata[3] = sline.sdata;
      bitperiod;
      rxdata[4] = sline.sdata;
      if (cfg.lcr[1:0] > 2'b00)
        begin
          bitperiod;
          rxdata[5] = sline.sdata;
        end
      else if (cfg.lcr[3])
        begin
          bitperiod;
          parity = sline.sdata; // 5 bits with parity
        end
      if (cfg.lcr[1:0] > 2'b00)
        begin
          if (cfg.lcr[1:0] > 2'b01)
            begin
              bitperiod;
              rxdata[6] = sline.sdata;
            end
          else if (cfg.lcr[3])
            begin
              bitperiod;
              parity = sline.sdata;
            end
        end
      if (cfg.lcr[1:0] > 2'b01)
        begin
          if (cfg.lcr[1:0] > 2'b10)
            begin
              bitperiod;
              rxdata[7] = sline.sdata;
            end
          else if (cfg.lcr[3])
            begin
              bitperiod;
              parity = sline.sdata;
            end
        end
      if (cfg.lcr[3] && (cfg.lcr[1:0] > 2'b10) )
        begin
          bitperiod;
          parity = sline.sdata;
        end
      if (cfg.lcr[3])
        begin
          pe = logic'(calparity (cfg.lcr, rxdata));
          if (pe != parity)
            pe = 1;
          else
            pe = 0;
        end
      // check for framing error - get to bit boundary
      repeat(8)
        @(posedge sline.clk);
      repeat(8)
        begin
          @(posedge sline.clk);
          if (sline.sdata == 1'b0)
            fe = 1;
        end
    end : rxchardetect
  end
endtask

task bitperiod;
  begin
    repeat(16)
      @(posedge sline.clk);
  end
endtask

endclass: uart_monitor

