//----------------------------------------------------------------------

// this uart is based on the 16550 uart but with an apb interface
//
// it has a similar pin-out and register map however it may
// not be exactly compatible in terms of functionality and
// timing
//
// it is provided as part of a verification environment and is
// not intended to be used as design ip

module uart_16550 (
  // apb signals
  input pclk,
  input presetn,
  input [31:0] paddr,
  input [31:0] pwdata,
  output[31:0] prdata,
  input pwrite,
  input penable,
  input psel,
  output pready,
  output pslverr,
  // uart interrupt request line
  output irq,
  // uart signals
  // serial input/output
  output txd,
  input rxd,
  // modem signals
  output nrts,
  output ndtr,
  output nout1,
  output nout2,
  input ncts,
  input ndsr,
  input ndcd,
  input nri,
  // baud rate generator output - needed for checking
  output baud_o
  );

// interconnect
// transmitter related:
wire tx_fifo_we;
wire tx_enable;
wire[4:0] tx_fifo_count;
wire tx_fifo_empty;
wire tx_fifo_full;
wire tx_busy;
wire txdout;
wire rxdin;
// receiver related:
wire[10:0] rx_data_out;
wire rx_idle;
wire rx_overrun;
wire parity_error;
wire framing_error;
wire break_error;
wire[4:0] rx_fifo_count;
wire rx_fifo_empty;
wire rx_fifo_full;
wire push_rx_fifo;
wire rx_enable;
wire rx_fifo_re;
wire loopback;

wire[7:0] lcr;

uart_register_file control(.pclk(pclk),
                           .presetn(presetn),
                           .psel(psel),
                           .pwrite(pwrite),
                           .penable(penable),
                           .paddr(paddr[6:2]),
                           .pwdata(pwdata),
                           .prdata(prdata),
                           .pready(pready),
                           .pslverr(pslverr),
                           .lcr(lcr),
                           // transmitter related signals
                           .tx_fifo_we(tx_fifo_we),
                           .tx_enable(tx_enable),
                           .tx_fifo_count(tx_fifo_count),
                           .tx_fifo_empty(tx_fifo_empty),
                           .tx_fifo_full(tx_fifo_full),
                           .tx_busy(tx_busy),
                           // receiver related signals
                           .rx_idle(rx_idle),
                           .rx_data_out(rx_data_out),
                           .rx_overrun(rx_overrun),
                           .parity_error(parity_error),
                           .framing_error(framing_error),
                           .break_error(break_error),
                           .rx_fifo_count(rx_fifo_count),
                           .rx_fifo_empty(rx_fifo_empty),
                           .rx_fifo_full(rx_fifo_full),
                           .push_rx_fifo(push_rx_fifo),
                           .rx_enable(rx_enable),
                           .rx_fifo_re(rx_fifo_re),
                           // modem interface related signals
                           .loopback(loopback),
                           .dsrn(ndsr),
                           .dcdn(ndcd),
                           .rin(nri),
                           .ctsn(ncts),
                           .rtsn(nrts),
                           .dtrn(ndtr),
                           .out1n(nout1),
                           .out2n(nout2),
                           .irq(irq),
                           .baud_o(baud_o)
                          );

// transmitter and tx fifo
uart_tx tx_channel(
  .pclk(pclk),
  .presetn(presetn),
  .pwdata(pwdata[7:0]),
  .tx_fifo_push(tx_fifo_we),
  .lcr(lcr),
  .enable(tx_enable),
  .tx_fifo_empty(tx_fifo_empty),
  .tx_fifo_full(tx_fifo_full),
  .tx_fifo_count(tx_fifo_count),
  .busy(tx_busy),
  .txd(txdout));

// receiver and rx fifo
uart_rx rx_channel(
  .pclk(pclk),
  .presetn(presetn),
  .rxd(rxdin),
  .pop_rx_fifo(rx_fifo_re),
  .enable(rx_enable),
  .lcr(lcr),
  .rx_idle(rx_idle),
  .rx_fifo_out(rx_data_out),
  .rx_fifo_count(rx_fifo_count),
  .push_rx_fifo(push_rx_fifo),
  .rx_fifo_empty(rx_fifo_empty),
  .rx_fifo_full(rx_fifo_full),
  .rx_overrun(rx_overrun),
  .parity_error(parity_error),
  .framing_error(framing_error),
  .break_error(break_error));


// handle loopback
assign rxdin = loopback ? txd : rxd;
assign txd = loopback ? 1'b1 : txdout;

endmodule: uart_16550

