`define ier 5'h1
`define iir 5'h2
`define fcr 5'h2
`define lcr 5'h3
`define mcr 5'h4
`define lsr 5'h5
`define msr 5'h6
`define div1 5'h7
`define div2 5'h8

// apb interface fsm states
