logic re;

// rx fifo over its threshold:
logic rx_fifo_over_threshold;

// uart registers:
logic[3:0] ier;
logic[3:0] iir;
logic[7:0] fcr;
logic[4:0] mcr;
logic[7:0] msr;
logic[3:0] lsr;
logic[15:0] divisor;


// baudrate counter
logic[15:0] dlc;
logic enable;
logic start_dlc;

// rx & tx enables
logic rx_enabled;
logic tx_enabled;

logic rx_overrun_int;
logic reset_overrun;

logic tx_int;
logic rx_int;
logic rx_parity_int;
logic rx_framing_int;
logic rx_break_int;
logic cts_0;
logic cts_1;
logic cts_int;
logic dcd_0;
logic dcd_1;
logic dcd_int;
logic dsr_0;
logic dsr_1;
logic dsr_int;
logic ri_0;
logic ri_1;
logic ri_int;

logic ms_int;
logic ndcd_1;
logic ncts_1;
logic ndsr_1;
logic nri_1;

logic ls_int;


logic fifo_error;

logic last_tx_fifo_empty;

// apb bus interface fsm:
apb_state fsm_state;

always @(posedge pclk)
  begin
    if (presetn == 0)
      begin
        we = 0;
        re = 0;
        pready = 0;
        fsm_state = idle;
      end
    else
      case (fsm_state)
        idle: begin
                we <= 0;
                re <= 0;
                pready <= 0;
                if (psel)
                  fsm_state <= setup;
              end
        setup: begin
                 re <= 0;
                 if (psel && penable)
                   begin
                     fsm_state <= access;
                     if (pwrite)
                       we <= 1;
                   end
                 else
                   fsm_state <= idle;
               end
        access: begin
                  pready <= 1;
                  we <= 0;
                  if(pwrite == 0)
                    re <= 1;
                  fsm_state <= idle;
                end
        default: fsm_state <= idle;
      endcase
  end

// one clock pulse per enable
assign baud_o = ~pclk && enable;

// interrupt line
always @(posedge pclk)
  begin
    if(presetn == 0) begin
      irq <= 0;
    end
    else if((re == 1) && (paddr == `iir)) begin
      irq <= 0;
    end
    else begin
      irq <= (ier[0] & rx_int) | (ier[1] & tx_int) | (ier[2] & ls_int) | (ier[3] & ms_int);
    end
  end

// loopback:
assign loopback = mcr[4];

// the register implementations:

// tx data register strobe
always @(posedge pclk)
  begin
    if(presetn == 0) begin
      tx_fifo_we <= 0;
    end
    else begin
      if((we == 1) && (paddr == `dr)) begin
        tx_fifo_we <= 1;
      end
      else begin
        tx_fifo_we <= 0;
      end
    end
  end

// divisor - baud rate divider
always @(posedge pclk)
  begin
    if(presetn == 0) begin
      divisor <= 0;
      start_dlc <= 0;
    end
    else begin
      if(we == 1) begin
        case(paddr)
