        endcase
      end
      else begin
        start_dlc <= 0;
      end
    end
  end

// lcr - line control register
always @(posedge pclk)
  begin
    if(presetn == 0) begin
      lcr <= 0;
    end
    else begin
      if((we == 1) && (paddr == `lcr)) begin
        lcr <= pwdata[7:0];
      end
    end
  end

// mcr - control register
always @(posedge pclk)
  begin
    if(presetn == 0) begin
      mcr <= 0;
    end
    else begin
      if((we == 1) && (paddr == `mcr)) begin
        mcr <= pwdata[4:0];
      end
    end
  end

