    if(presetn == 0) begin
      fcr <= 8'hc0;
    end
    else begin
      if((we == 1) && (paddr == `fcr)) begin
        fcr <= pwdata[7:0];
      end
    end
  end

// ier - interrupt masks:
always @(posedge pclk)
  begin
    if(presetn == 0) begin
      ier <= 0;
    end
    else begin
      if((we == 1) && (paddr == `ier)) begin
        ier <= pwdata[3:0];
      end
    end
  end

