//
// uart tx engine
//
module uart_tx(
  input pclk,
  input presetn,
  input[7:0] pwdata,
  input tx_fifo_push,
  input[7:0] lcr,
  input enable,
  output tx_fifo_empty,
  output tx_fifo_full,
  output[4:0] tx_fifo_count,
  output logic busy,
  output logic txd);

typedef enum {idle, start, bit0, bit1, bit2, bit3, bit4,
              bit5, bit6, bit7, parity, stop1, stop2} tx_fsm_t;

tx_fsm_t tx_state;
logic[3:0] bit_counter;
logic[7:0] tx_buffer;
wire[7:0] tx_fifo_out;
logic pop_tx_fifo;

// tx fifo:
uart_tx_fifo  tx_fifo(
                      .clk(pclk),
                      .rstn(presetn),
                      .push(tx_fifo_push),
                      .pop(pop_tx_fifo),
                      .data_in(pwdata),
                      .fifo_empty(tx_fifo_empty),
                      .fifo_full(tx_fifo_full),
                      .count(tx_fifo_count),
                      .data_out(tx_fifo_out));

// tx fsm:
always @(posedge pclk) begin
  if(presetn == 0) begin
    tx_state <= idle;
    bit_counter <= 0;
    tx_buffer <= 0;
    txd <= 1;
    pop_tx_fifo <= 0;
    busy <= 0;
  end
  else begin
    case(tx_state)
      idle: begin
              if((tx_fifo_empty == 0) && (enable == 1)) begin
                tx_state <= start;
                pop_tx_fifo <= 1;
                tx_buffer <= tx_fifo_out;
                busy <= 1;
                bit_counter <= 0;
              end
              else begin
                busy <= 0;
              end
            end
      start: begin
               pop_tx_fifo <= 0;
               txd <= 0;
               if((enable == 1) && (bit_counter == 4'hf)) begin
                 tx_state <= bit0;
               end
               if(enable == 1) begin
                 bit_counter <= bit_counter + 1;
               end
             end
      bit0: begin
              txd <= tx_buffer[0];
               if((enable == 1) && (bit_counter == 4'hf)) begin
                 tx_state <= bit1;
               end
               if(enable == 1) begin
                 bit_counter <= bit_counter + 1;
               end
             end
      bit1: begin
              txd <= tx_buffer[1];
               if((enable == 1) && (bit_counter == 4'hf)) begin
                 tx_state <= bit2;
               end
               if(enable == 1) begin
                 bit_counter <= bit_counter + 1;
               end
             end
      bit2: begin
              txd <= tx_buffer[2];
               if((enable == 1) && (bit_counter == 4'hf)) begin
                 tx_state <= bit3;
               end
               if(enable == 1) begin
                 bit_counter <= bit_counter + 1;
               end
             end
      bit3: begin
              txd <= tx_buffer[3];
               if((enable == 1) && (bit_counter == 4'hf)) begin
                 tx_state <= bit4;
               end
               if(enable == 1) begin
                 bit_counter <= bit_counter + 1;
               end
             end
      bit4: begin
              txd <= tx_buffer[4];
               if((enable == 1) && (bit_counter == 4'hf)) begin
                 if(lcr[1:0] != 0) begin
                   tx_state <= bit5;
                 end
                 else begin
                   if(lcr[3] == 1) begin
                     tx_buffer[7:5] = 0;
                     tx_state <= parity;
                   end
                   else begin
                     tx_state <= stop1;
                   end
                 end
               end
               if(enable == 1) begin
                 bit_counter <= bit_counter + 1;
               end
             end
      bit5: begin
              txd <= tx_buffer[5];
               if((enable == 1) && (bit_counter == 4'hf)) begin
                 if(lcr[1:0] > 2'b01) begin
                   tx_state <= bit6;
                 end
                 else begin
                   if(lcr[3] == 1) begin
                     tx_buffer[7:6] = 0;
                     tx_state <= parity;
                   end
                   else begin
                     tx_state <= stop1;
                   end
                 end
               end
               if(enable == 1) begin
                 bit_counter <= bit_counter + 1;
               end
             end
      bit6: begin
              txd <= tx_buffer[6];
               if((enable == 1) && (bit_counter == 4'hf)) begin
                 if(lcr[1:0] == 2'b11) begin
                   tx_state <= bit7;
                 end
                 else begin
                   if(lcr[3] == 1) begin
                     tx_buffer[7] = 0;
                     tx_state <= parity;
                   end
                   else begin
                     tx_state <= stop1;
                   end
                 end
               end
               if(enable == 1) begin
                 bit_counter <= bit_counter + 1;
               end
             end
      bit7: begin
              txd <= tx_buffer[7];
               if((enable == 1) && (bit_counter == 4'hf)) begin
                 if(lcr[3] == 1) begin
                   tx_state <= parity;
                 end
                 else begin
                   tx_state <= stop1;
                 end
               end
               if(enable == 1) begin
                 bit_counter <= bit_counter + 1;
               end
             end
      parity: begin
                case(lcr[5:3])
                  3'b001: txd <= ~(^tx_buffer);
                  3'b011: txd <= ^tx_buffer;
                  3'b101: txd <= 1;
                  3'b111: txd <= 0;
                  default: txd <= 0;
                endcase
                if((enable == 1) && (bit_counter == 4'hf)) begin
                  tx_state <= stop1;
                end
                if(enable == 1) begin
                  bit_counter <= bit_counter + 1;
                end
              end
       stop1: begin
                txd <=1;
                if((enable == 1) && (bit_counter == 4'hf)) begin
                  if(lcr[2] == 1) begin
                    tx_state <= stop2;
                  end
                  else begin
                      tx_state <= idle;
                  end
                end
                if(enable == 1) begin
                  bit_counter <= bit_counter + 1;
                end
              end
       stop2: begin
                txd <= 1;
                if((enable == 1) && (bit_counter == 4'hf)) begin
                    tx_state <= idle;
                end
                if(enable == 1) begin
                  bit_counter <= bit_counter + 1;
                end
              end
       default: tx_state <= idle;
     endcase
   end
end

property busy_bit;
  @(posedge pclk)
  tx_state == idle ##1 tx_state == start |->
    ((busy == 1) && (tx_state != idle))[*1:$] ##1 (tx_state == start);
endproperty: busy_bit

tx_busy_chk: assert property(busy_bit);


endmodule: uart_tx

