//   the license for the specific language governing
//   permissions and limitations under the license.
//----------------------------------------------------------------------

module uart_tb;

import uvm_pkg::*;
import uart_test_pkg::*;

logic pclk;
logic presetn;

apb_if apb(.pclk(pclk), .presetn(presetn));
serial_if rx_uart();
serial_if tx_uart();
modem_if modem();
interrupt_if irq();

// dut - a 16550 uart:
uart_16550 dut (
  // apb signals
  .pclk(pclk),
  .presetn(presetn),
  .paddr(apb.paddr),
  .pwdata(apb.pwdata),
  .prdata(apb.prdata),
  .pwrite(apb.pwrite),
  .penable(apb.penable),
  .psel(apb.psel[0]),
  .pready(apb.pready),
  .pslverr(apb.pslverr),
  // uart interrupt request line
  .irq(irq.irq),
  // uart signals
  // serial input/output
  .txd(tx_uart.sdata),
  .rxd(rx_uart.sdata),
  // modem signals
  .nrts(modem.nrts),
  .ndtr(modem.ndtr),
  .nout1(modem.out1),
  .nout2(modem.out2),
  .ncts(modem.ncts),
  .ndsr(modem.ndsr),
  .ndcd(modem.ndcd),
  .nri(modem.nri),
  // baud rate generator output - needed for the divisor checks
  .baud_o(irq.baud_out)
  );

// apb protocol monitor:
apb_monitor #(.no_slaves(1), .addr_width(32), .data_width(32))
  apb_protocol_monitor
  (
  .pclk(pclk),
  .presetn(presetn),
  .paddr(apb.paddr),
  .pwdata(apb.pwdata),
  .prdata(apb.prdata),
  .psel(apb.psel[0]),
  .pwrite(apb.pwrite),
  .penable(apb.penable),
  .pready(apb.pready),
  .pslverr(apb.pslverr));



// uvm virtual interface handling and run_test()
initial begin
  uvm_config_db #(virtual apb_if)::set(null, "uvm_test_top", "apb", apb);
  uvm_config_db #(virtual serial_if)::set(null, "uvm_test_top", "rx_uart", rx_uart);
  uvm_config_db #(virtual serial_if)::set(null, "uvm_test_top", "tx_uart", tx_uart);
  uvm_config_db #(virtual modem_if)::set(null, "uvm_test_top", "modem", modem);
  uvm_config_db #(virtual interrupt_if)::set(null, "uvm_test_top", "irq", irq);
  run_test();
end


// simple clock/reset
initial begin
  pclk = 0;
  presetn = 0;
  repeat(10) begin
    #1ns pclk = ~pclk;
  end
  presetn = 1;
  forever begin
    #1ns pclk = ~pclk;
  end
end

// some interface signal assignments:
assign irq.clk = pclk;
assign modem.clk = pclk;
assign rx_uart.clk = irq.baud_out;
assign tx_uart.clk = irq.baud_out;

endmodule: uart_tb

